import importlib
import os
import subprocess
import sys
import argparse
import json
from . import tl_config
from . import resources

HELP_TEXT = """Collect the resource from the NodeB

the information on how to connect to the nodeb is retrieved from the testline
configuration. You need provide the testline configuration by the path to the
testline respository and the testline name.
By default, the current host name is derived to formulate the testline name and
the testline configuration repository is expected to be in /home/ute/testline_configuration

If You do not have a local checkout of the testline_configuration, you can clone it from:
git@wrgitlab.ext.net.nokia.com:RAN/configuration-management/testline_configuration.git
"""


def get_tl_name_from_host():
    """Get the testline name by the hostname"""
    host_name, _ = subprocess.Popen(['hostname'], stdout=subprocess.PIPE).communicate()
    return host_name.decode('UTF-8').strip().replace('-', '_')


def import_config_module(module_name, tl_config_path):
    """Import the testline configuration. The python path is udated, so the testine configuration
    is found within the given path of the testline config repository

    :param module_name: The module to import containing the testline configuration
    :param tl_config_path: The path to the testline configuration repository
    """
    if not os.path.exists(tl_config_path):
        raise AssertionError('The path does not exist: [{}] repository of testline_configuration not found!'.
                             format(tl_config_path))
    sys.path.append(tl_config_path)
    return importlib.import_module(module_name)


def load_local_testline_config(tl_config_path, tl_name=None):
    """Imports the testline configuration from the __init__.py configuration file
    :param tl_config_path: the path to the testline configuration repository
    :param tl_name: The name of the testline, corresponding to the foldername of the tl
    """
    if tl_name is None:
        module_name = get_tl_name_from_host()
    else:
        module_name = tl_name

    try:
        mm = import_config_module(module_name, tl_config_path)
        return mm.tl
    except ImportError:
        raise AssertionError("No testline configuration found!!")


def read_input(query_string):
    """Query information from user

    :param query_string: String to prompt to user
    """
    return input(query_string)


def parse_arguments():
    """Parses the arguments of the console script call
    """
    parser = argparse.ArgumentParser(prog='collect_resources',
                                     description=HELP_TEXT,
                                     epilog='Resource collection',
                                     formatter_class=argparse.RawTextHelpFormatter)
    parser.add_argument('-i', '--nodeid', default='0',
                        help='The array index of the nodeb in the tl config (default: 0)')
    parser.add_argument('-t', '--nodetype', default='gnb', help='type of NodeB, gnb or enb (default=gnb)')
    parser.add_argument('-c', '--tlconfigpath',
                        default='/home/ute/testline_configuration',
                        help='Path to tl config repository, default: /home/ute/testline_configuration')
    parser.add_argument('-n', '--tlname', help='Name of the testline (by default taken from hostname)')
    parser.add_argument('filename', help='The filename to save the json data to')

    args = parser.parse_args()

    if args.nodetype not in ['gnb', 'enb']:
        raise AssertionError('Wrong node type given! Only gnb and enb are supported!')

    return args


def write_resources(filename, resources):
    """Writes the json resource data to the given filename

    :param filename: The file to write to
    :param resources: The resource data to be written.
    """
    if os.path.exists(filename):
        user_input = read_input("File '{}' exists! Overwrite? [y/n]:".format(filename))
        if user_input.lower() not in ['y', 'yes']:
            return

    with open(filename, 'w') as json_out:
        json.dump(resources, json_out, indent=4)


def collect_resources():
    args = parse_arguments()
    tl = load_local_testline_config(tl_config_path=args.tlconfigpath, tl_name=args.tlname)
    tl_config.TL_CONFIG = tl

    collected_resources = resources.get_resources(node_id=int(args.nodeid),
                                                  node_type=args.nodetype,
                                                  detailed=True)

    write_resources(args.filename, collected_resources)
